import{_ as n,o as a,c as s,a2 as t}from"./chunks/framework.CcJ8wlZS.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Wiki Fabric","text":"Git-native knowledge governance for AI coding agents","tagline":"Project memory that is scoped by precedence, traceable to evidence, enforced by CI — and provably delivered before an agent writes code.","actions":[{"theme":"brand","text":"Why Wiki Fabric","link":"./why"},{"theme":"alt","text":"Quick Start","link":"https://github.com/hybridindie/wiki-fabric#quick-start"},{"theme":"alt","text":"GitHub","link":"https://github.com/hybridindie/wiki-fabric"}]},"features":[{"title":"Compiles sources into verified claims","details":"LLM extracts atomic assertions with line-level locators and verbatim quotes. Provenance is mandatory — lint refuses claims without sources."},{"title":"Promotes patterns with measured maturity","details":"Experience events are deterministically clustered into dossiers. Promotion requires ≥2 independent projects and human review."},{"title":"Enforces scope precedence at task time","details":"wf context compiles project decisions > domain patterns > global policies into a manifest where every inclusion and exclusion carries a reason."},{"title":"Measures behavior, not vibes","details":"Behavior evals verify the knowledge actually changes agent decisions. The compiler has its own golden-corpus eval. CI fails on regression."}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),i={name:"index.md"};function o(r,e,p,c,l,d){return a(),s("div",null,[...e[0]||(e[0]=[t(`<h2 id="the-proof-in-one-session" tabindex="-1">The proof in one session <a class="header-anchor" href="#the-proof-in-one-session" aria-label="Permalink to &quot;The proof in one session&quot;">​</a></h2><p>A fabric containing one pattern, one anti-pattern, and one project decision changes what an agent is <em>told</em> before it writes code:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>▸ Agent asks for task context: &quot;Add token refresh to the auth service&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Selected</span></span>
<span class="line"><span>### Project (highest precedence)</span></span>
<span class="line"><span>- [[decision-rotation-over-sessions]] — project match: auth-service</span></span>
<span class="line"><span>### Global</span></span>
<span class="line"><span>- [[anti-pattern-shared-token-cache]] — global pattern match: token</span></span>
<span class="line"><span>- [[pattern-token-rotation]] — global pattern match: refresh, token</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Excluded</span></span>
<span class="line"><span>- \`patterns/pattern-superseded.md\` — superseded</span></span>
<span class="line"><span>- \`patterns/pattern-stale.md\` — stale: review_after overdue 255 days</span></span>
<span class="line"><span></span></span>
<span class="line"><span>✓ anti-pattern warning delivered: agent is told NOT to build a shared token cache</span></span>
<span class="line"><span>✓ project decision delivered: binding, highest precedence</span></span>
<span class="line"><span>✓ correct alternative delivered: per-session cache</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PROOF: without the fabric, an LLM would plausibly implement the banned shared cache.</span></span>
<span class="line"><span>With the manifest, the banned approach is named in the prompt BEFORE code is written.</span></span></code></pre></div><p>Run it yourself with <code>bash scripts/demo.sh</code> — no install required.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><strong>Very early alpha — expect breaking changes.</strong> The core loop works end-to-end (verified on real projects), but schemas move without migration scripts and nothing is packaged yet. Useful today if you want to shape the direction; not yet load-bearing team infrastructure.</p></div>`,5)])])}const m=n(i,[["render",o]]);export{u as __pageData,m as default};
